104	    /** Move a claim to a new status; a change its status does not allow is refused, as is settling
105	     *  by the user who opened the claim. A clerk's settling of a claim whose due is above the sheet's
106	     *  clerk limit leaves it PENDING for a steward to approve (a due of n/a is within any limit; a
107	     *  steward settles anything). */
108	    @Transactional
109	    public Claim changeStatus(String sheetId, String user, long id, ClaimStatus next) {
110	        Claim claim = claims.findForUpdate(id, sheetId)
111	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim."));
112	        refuseIfClosed(sheetId, claim.getDate());
113	        if (!claim.getStatus().canBecome(next)) {
114	            throw new ResponseStatusException(HttpStatus.CONFLICT,
115	                    "A " + claim.getStatus() + " claim cannot become " + next + ".");
116	        }
117	        if (next == ClaimStatus.SETTLED && user.equals(claim.getOpenedBy())) {
118	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
119	                    "The user who opened a claim cannot settle it.");
120	        }
121	        Person person = person(sheetId, claim.getPersonId());
122	        // Worked out while the claim is still open: settling freezes the due, its late charge included.
123	        BigDecimal dueNow = next == ClaimStatus.SETTLED ? due(sheetId, person, claim) : null;
124	        if (next == ClaimStatus.SETTLED && isAboveClerkLimit(sheetId, user, dueNow)) next = ClaimStatus.PENDING;
125	        Rollup.Snapshot before = rollup.snapshot(sheetId);
126	        String number = next == ClaimStatus.OPEN ? nextNumber(sheetId, claim) : claim.getNumber();
127	        claim.setStatus(next);
128	        if (next == ClaimStatus.OPEN) claim.setOpenedBy(user);
129	        // A voided claim keeps its number, which is never given to another claim.
130	        claim.setNumber(number);
131	        if (next == ClaimStatus.SETTLED) claim.setSettledDue(dueNow);
132	        logStatus(sheetId, user, person, claim);
133	        Claim saved = claims.saveAndFlush(claim);
134	        String event = EVENTS.get(next);
135	        if (next == ClaimStatus.SETTLED) {
136	            recordChange(event, user, person, saved, number, " due=" + text(saved.getSettledDue()));
137	        } else {
138	            recordChange(event, user, person, saved, number, "");
139	        }
140	        rollup.recordChanges(user, before);
141	        return saved;
142	    }
