144	    /** Move a DRAFT, OPEN or PENDING claim to another person on the sheet, as their newest claim. It
145	     *  keeps its number and date and loses any figure a statement bound it to (it is live again until
146	     *  its new person's next statement). Refused unless the user is a steward of the sheet, and for a
147	     *  settled or voided claim, a claim dated inside a closed period, a move to the claim's own person,
148	     *  or to a person retired by the claim's date. */
149	    @Transactional
150	    public Claim reassign(String sheetId, String user, long id, long toPersonId) {
151	        Claim claim = claims.findForUpdate(id, sheetId)
152	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim."));
153	        refuseIfClosed(sheetId, claim.getDate());
154	        if (settings.roleOf(sheetId, user) != Role.STEWARD) {
155	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward moves a claim to another person.");
156	        }
157	        if (claim.getStatus() != ClaimStatus.DRAFT && !claim.getStatus().isOpen()) {
158	            throw new ResponseStatusException(HttpStatus.CONFLICT,
159	                    "A " + claim.getStatus() + " claim cannot be moved to another person.");
160	        }
161	        Person from = person(sheetId, claim.getPersonId());
162	        Person to = person(sheetId, toPersonId);
163	        if (from.getId().equals(to.getId())) {
164	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The claim is already " + to.getName() + "'s.");
165	        }
166	        refuseIfRetired(to, claim.getDate());
167	        Rollup.Snapshot before = rollup.snapshot(sheetId);
168	        claim.moveTo(to.getId(), claims.lastListed(sheetId) + 1);
169	        Claim saved = claims.saveAndFlush(claim);
170	        recordChange("CLAIM_REASSIGNED", user, to, saved, saved.getNumber(),
171	                " from=" + from.getName() + " to=" + to.getName());
172	        rollup.recordChanges(user, before);
173	        return saved;
174	    }
