176	    /** Approve a PENDING claim: it is SETTLED, its due (its live figure and any late charge) frozen
177	     *  now. Refused unless the user is a steward of the sheet other than the one who opened it. */
178	    @Transactional
179	    public Claim approve(String sheetId, String user, long id) {
180	        Claim claim = pending(sheetId, user, id);
181	        if (user.equals(claim.getOpenedBy())) {
182	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
183	                    "The user who opened a claim cannot approve it.");
184	        }
185	        Person person = person(sheetId, claim.getPersonId());
186	        BigDecimal dueNow = due(sheetId, person, claim);
187	        Rollup.Snapshot before = rollup.snapshot(sheetId);
188	        claim.setStatus(ClaimStatus.SETTLED);
189	        claim.setSettledDue(dueNow);
190	        logStatus(sheetId, user, person, claim);
191	        Claim saved = claims.saveAndFlush(claim);
192	        recordChange("CLAIM_APPROVED", user, person, saved, saved.getNumber(), " due=" + text(saved.getSettledDue()));
193	        rollup.recordChanges(user, before);
194	        return saved;
195	    }
