197	    /** Re-settle a SETTLED claim: its due is frozen again at what it would be today as an open claim
198	     *  bound by no statement (today's rates, grades, floor and late charge). Refused unless the user is
199	     *  a steward of the sheet, and for a claim that is not SETTLED or is dated inside a closed period. */
200	    @Transactional
201	    public Claim resettle(String sheetId, String user, long id) {
202	        Claim claim = claims.findForUpdate(id, sheetId)
203	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim."));
204	        refuseIfClosed(sheetId, claim.getDate());
205	        if (settings.roleOf(sheetId, user) != Role.STEWARD) {
206	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward re-settles a claim.");
207	        }
208	        if (claim.getStatus() != ClaimStatus.SETTLED) {
209	            throw new ResponseStatusException(HttpStatus.CONFLICT,
210	                    "A " + claim.getStatus() + " claim cannot be re-settled; only a SETTLED one can.");
211	        }
212	        Person person = person(sheetId, claim.getPersonId());
213	        BigDecimal old = claim.getSettledDue();
214	        BigDecimal dueNow = LateCharge.dueAsOpen(claim, dueNow(sheetId, person, claim), sheets.today(sheetId),
215	                settings.latePct(sheetId, claim.getDate()), rounding(sheetId, claim));
216	        Rollup.Snapshot before = rollup.snapshot(sheetId);
217	        claim.setSettledDue(dueNow);
218	        logStatus(sheetId, user, person, claim);
219	        Claim saved = claims.saveAndFlush(claim);
220	        recordChange("CLAIM_RESETTLED", user, person, saved, saved.getNumber(),
221	                " old=" + text(old) + " new=" + text(saved.getSettledDue()));
222	        rollup.recordChanges(user, before);
223	        return saved;
224	    }
