226	    /** Reject a PENDING claim for a reason: it is OPEN again, bound again by its person's last
227	     *  statement if that statement bound it. Refused unless the user is a steward of the sheet. */
228	    @Transactional
229	    public Claim reject(String sheetId, String user, long id, String reason) {
230	        Claim claim = pending(sheetId, user, id);
231	        Person person = person(sheetId, claim.getPersonId());
232	        Rollup.Snapshot before = rollup.snapshot(sheetId);
233	        claim.setStatus(ClaimStatus.OPEN);
234	        logStatus(sheetId, user, person, claim);
235	        Claim saved = claims.saveAndFlush(claim);
236	        recordChange("CLAIM_REJECTED", user, person, saved, saved.getNumber(), " reason=" + reason);
237	        rollup.recordChanges(user, before);
238	        return saved;
239	    }
