241	    /** The PENDING claim a steward approves or rejects, locked; refused when it is not PENDING, is
242	     *  dated inside a closed period, or the user is not a steward of the sheet. */
243	    private Claim pending(String sheetId, String user, long id) {
244	        Claim claim = claims.findForUpdate(id, sheetId)
245	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim."));
246	        refuseIfClosed(sheetId, claim.getDate());
247	        if (claim.getStatus() != ClaimStatus.PENDING) {
248	            throw new ResponseStatusException(HttpStatus.CONFLICT,
249	                    "A " + claim.getStatus() + " claim is not waiting for approval.");
250	        }
251	        if (settings.roleOf(sheetId, user) != Role.STEWARD) {
252	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward approves or rejects a claim.");
253	        }
254	        return claim;
255	    }
256	
257	    private static final Map<ClaimStatus, String> EVENTS = Map.of(
258	            ClaimStatus.OPEN, "CLAIM_OPENED", ClaimStatus.PENDING, "CLAIM_PENDING",
259	            ClaimStatus.SETTLED, "CLAIM_SETTLED", ClaimStatus.VOID, "CLAIM_VOIDED");
260	
261	    private static String text(BigDecimal due) {
262	        return due == null ? "n/a" : due.toPlainString();
263	    }
264	
265	    /** The number a claim takes as it is opened: while the sheet's period numbering is in force (its
266	     *  today on or after the setting's date), the next of the claim's period, <period name>-<n>, or of
267	     *  claims in no period, X-<n>; otherwise the sheet's next sheet-wide number. */
268	    private String nextNumber(String sheetId, Claim claim) {
269	        LocalDate from = settings.periodNumberingFrom(sheetId);
270	        if (from == null || sheets.today(sheetId).isBefore(from)) {
271	            return Integer.toString(sheets.nextClaimNumber(sheetId));
272	        }
273	        Period period = periods.findBySheetIdOrderByFromAsc(sheetId).stream()
274	                .filter((p) -> p.contains(claim.getDate())).findFirst().orElse(null);
275	        if (period == null) return "X-" + sheets.nextSequenceNumber(sheetId, "none");
276	        return period.getName() + "-" + sheets.nextSequenceNumber(sheetId, "period:" + period.getId());
277	    }
278	
279	    /** Whether the user is a clerk settling a claim whose due is above the sheet's clerk limit. */
280	    private boolean isAboveClerkLimit(String sheetId, String user, BigDecimal due) {
281	        if (due == null || settings.roleOf(sheetId, user) == Role.STEWARD) return false;
282	        BigDecimal limit = settings.clerkLimit(sheetId);
283	        return limit != null && due.compareTo(limit) > 0;
284	    }
