286	    /** Refuse a change to a claim dated inside a closed period. The sheet is locked first, as closing
287	     *  a period locks it, so a claim cannot change in a period while it is being closed. */
288	    private void refuseIfClosed(String sheetId, LocalDate date) {
289	        sheetRows.findForUpdate(sheetId);
290	        if (periods.isClosedOn(sheetId, date)) {
291	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The claim is dated inside a closed period.");
292	        }
293	    }
294	
295	    /** Refuse a correction (a negative amount) unless it names, by number, a settled claim of the same person. */
296	    private void refuseIfNotCorrecting(String sheetId, long personId, BigDecimal amount, String corrects) {
297	        if (amount.signum() >= 0) return;
298	        boolean settled = corrects != null && claims.findBySheetIdAndPersonIdAndNumber(sheetId, personId, corrects)
299	                .filter(c -> c.getStatus() == ClaimStatus.SETTLED).isPresent();
300	        if (!settled) {
301	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
302	                    "A negative amount must name, by number, a settled claim of the same person that it corrects.");
303	        }
304	    }
305	
306	    /** Refuse a claim dated after its person's retirement date. */
307	    private static void refuseIfRetired(Person person, LocalDate date) {
308	        if (person.isRetiredOn(date)) {
309	            throw new ResponseStatusException(HttpStatus.CONFLICT,
310	                    "The claim is dated after " + person.getName() + " retired.");
311	        }
312	    }
313	
314	    private Person person(String sheetId, long personId) {
315	        return people.findByIdAndSheetId(personId, sheetId)
316	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person."));
317	    }
318	
319	    /** What is due on the claim now: its figure with the late charge on top while it is open and
320	     *  overdue (the charge is never bound by a statement); null when the figure is n/a. */
321	    public BigDecimal due(String sheetId, Person person, Claim claim) {
322	        return LateCharge.dueOf(claim, figure(sheetId, person, claim), sheets.today(sheetId),
323	                settings.latePct(sheetId, claim.getDate()), rounding(sheetId, claim));
324	    }
325	
326	    /** The figure under the claim's due, before any late charge: the due fixed when it was settled, else the figure
327	     *  its person's last statement bound it to (unless it is PENDING, which no statement binds), else its live due;
328	     *  null when that is n/a. */
329	    public BigDecimal figure(String sheetId, Person person, Claim claim) {
330	        if (claim.getSettledDue() != null) return claim.getSettledDue();
331	        if (claim.isBound()) return claim.getStatedDue();
332	        return dueNow(sheetId, person, claim);
333	    }
334	
335	    /** What is due on the claim now at the rate in force on the claim's date of its person's grade in
336	     *  force on that date, rounded
337	     *  as the claim's {@link Rounding} decides and at least the sheet's floor (a correction has no floor); null when no rate of the
338	     *  grade applies by then. */
339	    private BigDecimal dueNow(String sheetId, Person person, Claim claim) {
340	        Rate rate = rates.inForce(sheetId, person.gradeOn(claim.getDate()), claim.getDate());
341	        if (rate == null) return null;
342	        BigDecimal due = claim.getAmount().multiply(rate.getPct()).divide(BigDecimal.valueOf(100), 2,
343	                rounding(sheetId, claim));
344	        return claim.isCorrection() ? due : due.max(settings.floor(sheetId, claim.getDate()));
345	    }
346	
347	    /** How the claim's live figures round under the sheet's policy date: by the date of the claim a
348	     *  correction corrects, else by its own. */
349	    private RoundingMode rounding(String sheetId, Claim claim) {
350	        Claim corrected = claim.isCorrection() && claim.getCorrects() != null
351	                ? claims.findBySheetIdAndPersonIdAndNumber(sheetId, claim.getPersonId(), claim.getCorrects()).orElse(null)
352	                : null;
353	        return Rounding.of(Rounding.dateOf(claim, corrected),
354	                Rounding.policyDate(settings.policyDate(sheetId), sheets.today(sheetId)));
355	    }
356	
357	    /** Log the status the claim has just taken, with its due as worked out now. */
358	    private void logStatus(String sheetId, String user, Person person, Claim claim) {
359	        claim.logStatus(user, sheets.today(sheetId), due(sheetId, person, claim));
360	    }
361	
362	    private void recordChange(String event, String user, Person person, Claim claim) {
363	        recordChange(event, user, person, claim, claim.getNumber(), "");
364	    }
365	
366	    /** The claim's audit line; a claim with a number carries it, then any extra fields. */
367	    private void recordChange(String event, String user, Person person, Claim claim, String number, String extra) {
368	        audit.recordOnCommit(event + " sheet=" + claim.getSheetId() + " by=" + user + " person=" + person.getName()
369	                + " amount=" + claim.getAmount().toPlainString() + " date=" + claim.getDate()
370	                + (number == null ? "" : " number=" + number) + extra);
371	    }
372	
373	    private LocalDate dateOr(String sheetId, LocalDate date) {
374	        return date != null ? date : sheets.today(sheetId);
375	    }
376	
377	    private static String noteOf(String note) {
378	        return note == null ? "" : note.trim();
379	    }
380	}
