package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.time.temporal.ChronoUnit;

/**
 * The late charge on a claim: an open claim past its due-by (fixed when it was added) gains
 * the sheet's late percent of its figure for every full 30 days it is overdue, rounded as the claim's
 * {@link Rounding} decides, like due; a correction gains none. A statement never binds the charge; it follows the sheet's today until the claim is settled.
 */
public final class LateCharge {

    /** The days a claim must be overdue for each step of the late charge. */
    public static final int DAYS_PER_CHARGE = 30;

    private static final BigDecimal ZERO = BigDecimal.ZERO.setScale(2);

    private LateCharge() {
    }

    /** The late charge on the claim of the figure (null: n/a, and no charge) on the sheet's today. */
    public static BigDecimal of(Claim claim, BigDecimal figure, LocalDate today, BigDecimal latePct,
            RoundingMode rounding) {
        return claim.getStatus().isOpen() ? asOpen(claim, figure, today, latePct, rounding) : ZERO;
    }

    /** The late charge the claim of the figure would have on the sheet's today were it open. */
    private static BigDecimal asOpen(Claim claim, BigDecimal figure, LocalDate today, BigDecimal latePct,
            RoundingMode rounding) {
        if (figure == null || today == null || claim.isCorrection()) return ZERO;
        long overdueDays = ChronoUnit.DAYS.between(claim.getDueBy(), today);
        long steps = overdueDays <= 0 ? 0 : overdueDays / DAYS_PER_CHARGE;
        if (steps == 0) return ZERO;
        return figure.multiply(latePct).multiply(BigDecimal.valueOf(steps))
                .divide(BigDecimal.valueOf(100), 2, rounding);
    }

    /** The figure with its late charge added on top; null when the figure is n/a. */
    public static BigDecimal dueOf(Claim claim, BigDecimal figure, LocalDate today, BigDecimal latePct,
            RoundingMode rounding) {
        return figure == null ? null : figure.add(of(claim, figure, today, latePct, rounding));
    }

    /** The figure with the late charge it would have were the claim open added on top; null when the figure is n/a. */
    public static BigDecimal dueAsOpen(Claim claim, BigDecimal figure, LocalDate today, BigDecimal latePct,
            RoundingMode rounding) {
        return figure == null ? null : figure.add(asOpen(claim, figure, today, latePct, rounding));
    }
}
        audit.recordOnCommit("PERIOD_ADDED sheet=" + sheetId + " by=" + user + " period=" + saved.getName()
                + " from=" + saved.getFrom() + " to=" + saved.getTo());
        return saved;
    }

    /** Close a period, fixing at this moment its due-total and each person's due-total for it: the figures of the open and settled claims
     *  dated in it, skipping those that are n/a and the unbound open claims dated within a hold of their person. Refused when the period is already closed. */
    @Transactional
    public Period close(String sheetId, String user, long id) {
        // Locked as claim changes lock it, so no claim in the period changes while it is closed.
        sheetRows.findForUpdate(sheetId);
        Period period = periods.findByIdAndSheetId(id, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such period."));
        if (period.isClosed()) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "The period is already closed.");
        }
        Map<Long, Person> peopleById = people.findBySheetIdOrderByIdAsc(sheetId).stream()
                .collect(Collectors.toMap(Person::getId, Function.identity()));
        BigDecimal total = BigDecimal.ZERO.setScale(2);
        Map<Long, BigDecimal> personTotals = new HashMap<>();
        for (Long personId : peopleById.keySet()) personTotals.put(personId, BigDecimal.ZERO.setScale(2));
        for (Claim claim : claims.findBySheetIdOrderByIdDesc(sheetId)) {
            Person person = peopleById.get(claim.getPersonId());
            if (person == null) continue;
            boolean counts = claim.getStatus() == ClaimStatus.SETTLED
                    || (claim.getStatus().isOpen() && (claim.isBound() || !person.isHeldOn(claim.getDate())));
            if (!counts || !period.contains(claim.getDate())) continue;
            BigDecimal due = claimService.due(sheetId, person, claim);
            if (due != null) {
                total = total.add(due);
                personTotals.merge(person.getId(), due, BigDecimal::add);
            }
        }
        period.close(total, personTotals);
        Period saved = periods.saveAndFlush(period);
        audit.recordOnCommit("PERIOD_CLOSED sheet=" + sheetId + " by=" + user + " period=" + saved.getName()
                + " total=" + total.toPlainString());
        return saved;
    }

    /** Reopen a closed period, making its due-total live again. Refused when the user is not a steward
     *  of the sheet, or the period is not closed. */
    @Transactional
    public Period reopen(String sheetId, String user, long id) {
        // Locked as closing locks it, so a reopen and a close of the period do not cross.
        sheetRows.findForUpdate(sheetId);
        Period period = periods.findByIdAndSheetId(id, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such period."));
        if (settings.roleOf(sheetId, user) != Role.STEWARD) {
            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward can reopen a period.");
        }
        if (!period.isClosed()) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "The period is not closed.");
        }
        period.reopen();
        Period saved = periods.saveAndFlush(period);
        audit.recordOnCommit("PERIOD_REOPENED sheet=" + sheetId + " by=" + user + " period=" + saved.getName());
        return saved;
    }

    private static ResponseStatusException nameInUse() {
        return new ResponseStatusException(HttpStatus.CONFLICT, "That period name is already in use on the sheet.");
    }
}
